namespace ChilliCream.Analyzers.Tests;

public sealed partial class SimplifyNameAnalyzerTests
{
    [Fact]
    public async Task Analyze_Should_ReportNothing_When_AutoGeneratedHeader()
    {
        // arrange
        const string source =
            """
            // <auto-generated/>
            using System.Text;

            class C
            {
                System.Text.StringBuilder M() => new();
            }
            """;

        // act & assert
        await VerifyAsync(source);
    }

    [Fact]
    public async Task Analyze_Should_ReportNothing_When_DirectiveInsideName()
    {
        // arrange
        const string source =
            """
            using System.Text;

            class C
            {
                System.
            #if true
                Text.
            #endif
                StringBuilder M() => new();
            }
            """;

        // act & assert
        await VerifyAsync(source);
    }

    [Fact]
    public async Task Analyze_Should_ReportNothing_When_ExternAliasDirective()
    {
        // arrange
        const string source =
            """
            extern alias {|CS0430:Lib|};

            class C
            {
            }
            """;

        // act & assert
        await VerifyAsync(source);
    }

    [Fact]
    public async Task Analyze_Should_ReportNothing_When_GeneratedFileName()
    {
        // arrange
        var test = CreateTest(string.Empty);
        test.TestState.Sources.Add(
            (
                "Widget.g.cs",
                """
                using System.Text;

                class C
                {
                    System.Text.StringBuilder M() => new();
                }
                """));

        // act & assert
        await test.RunAsync(TestContext.Current.CancellationToken);
    }

    [Fact]
    public async Task Analyze_Should_ReportNothing_When_NamespaceDeclarationName()
    {
        // arrange
        var test = CreateTest(
            """
            namespace Company.Product
            {
            }
            """);
        test.TestState.Sources.Add(
            """
            namespace Company.Product.Feature;
            """);

        // act & assert
        await test.RunAsync(TestContext.Current.CancellationToken);
    }

    [Fact]
    public async Task Analyze_Should_ReportNothing_When_UsingDirectives()
    {
        // arrange
        const string source =
            """
            global using static System.Math;
            using System.Text;
            using static System.Text.Encoding;
            using Builder = System.Text.StringBuilder;
            """;

        // act & assert
        await VerifyAsync(source);
    }

    [Fact]
    public async Task Analyze_Should_ReportNothing_When_UsingDirectivesInNamespace()
    {
        // arrange
        const string source =
            """
            using System.Text;

            namespace Company
            {
                using static System.Text.Encoding;
                using Builder = System.Text.StringBuilder;
            }
            """;

        // act & assert
        await VerifyAsync(source);
    }
}
